INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('Xiew4eU8wUGr9KmxOmRl', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-03-25T18:52:29.941Z'::timestamptz, 'Cassiane Lemos Fausto', 'cassianefausto@gmail.com', '41999647454', '51', 'Vendedora', 'Sou a irmã  caçula de 5 irmãos, minha infância foi tranquila  com meus irmãos amigos e primos . Minha tia fazia bolo pras bonecas eu dormia  na mesa de costura da minha mãe.  Comia coxinha com meu pai e ele me ensinou a nadar. Minha vó  fazia balas e contava histórias. Adorava as costureiras que trabalhavam com minha mãe.  Ia sozinha pra escola  e levava minha amiga junto   adorava subir em árvores  e brincar na água', 'Namorei muito, experimentei  muitas coisas, trabalhei como recreaçionista e em banco, estudei escola de freira  e escola pública. Fiz dança, natação, arte marcial.  Fui morar  sozinha com meu namorado ( atual pai da minha filha )  com 19 anos  . Perdi meu pai com 16 anos. Tive  muitos amigos  e me formei em administração. Sempre discuti muito com minha mãe  mas no geral  nos dávamos bem. Ela viajava comigo sempre pra são  Paulo', 'Fui morar junto com carlos ( com o pai da Bárbara  minha filha  que hj tem 22 anos ).  Início  minha carreira  na área de comunicação  visual e vendas . Vivi com o Carlos até 30 anos  quando a Bah  nasceu, minha mãe morreu e me separei  tudo em 2 meses e meio  tive uma empresa com  meu ex sogro.   Tive um relacionamento  abusivo . Depois amei muito uma pessoa por 6 anos e hoje sou casada com o homem  da minha vida . Faz 3 anos, adoro sair e viajar . Tenho  minha casa e minha empresa. Minha filha já tentou suicídio.  Ela é  bi e vivemos bem depois de dias turbulentos e depressão', 'No momento quero saber o que fazer após 51 anos sendo que tenho uma tendinite  e uma hérnia.  Horrível escrever tudo isso  dói tudo', 'A vida toda.  Coaching, cursos, terapias, constelação.. tudo.', '9', 'Acima de R$ 8.000', 'Não tenho condições de investir', 'Watts', NULL, NULL, '[{"nome": "TRAVA DA COMPETÊNCIA", "score": 7.6}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 7.2}, {"nome": "TRAVA DO SERVIDOR", "score": 5.4}, {"nome": "TRAVA DA APROVAÇÃO", "score": 4.6}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 3.8}, {"nome": "TRAVA DA ESCASSEZ", "score": 3.4}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 2.8}, {"nome": "TRAVA DA VÍTIMA", "score": 2.8}, {"nome": "TRAVA PATERNA", "score": 2.4}, {"nome": "TRAVA DO AMBIENTE", "score": 1.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('dmSSsDTVgmcUhS2Brl2a', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-03-26T04:26:54.449Z'::timestamptz, 'Adriana Aparecida Bosso', 'drib2107@gmail.com', '41997313553', '53', 'Fiscal de caixa de supermercado', 'Houve brigas e muitas por falta de dinheiro, tínhamos comércio,meu pai gastava todo lucro em negócios errados,ele e minha mãe brigavam, nós éramos mais empregadas q filhas, irmã caçula, nunca podia fazer o q queria em casa,minhas irmãs mais velhas q mandavam,nossa mãe nunca teve tempo pra nós,qnd eu precisava era minha irmã mais velha já falecida q cuidava de mim, fiquei adulta, saí de casa pra trabalhar e ainda mandava dinheiro ou trazia pra ajudar nas despesas do comércio,meu pai sempre doente faleceu e sempre fui eu que mais ajudava,hj sou divorciada,tenho 1 filho de 15 anos ,minha mãe de 83 pra cuidar minha irmã não ajuda a cuidar dela ,estou endividada, sempre correndo atrás,trabalhando muito pra sustentar a casa, comendo hj pra pagar amanhã,sonhando muito e com fé,pq sei q meu dia vai chegar,entrei na aliança em fevereiro, até agora só escutando os áudios, não consigo idealizar meu sonho grande,nem meu plano perfeito,sempre mudando ,comecei a rodar o protocolo de dependência emocional,mas não consigo finalizar, sempre acontece alguma coisa ou o cansaço me derruba,trabalhei 34 anos no balcão de uma farmácia e no final de janeiro desse ano saí e virei fiscal de supermercado pra ficar perto de casa,cansada, sempre tentando novos meios de sair do CLT pra ganhar mais e ter mais tempo pra minha família,tbm comecei no empreendedorismo com marketing multi nível, procurando pessoas pra trabalhar comigo na Akmos....', 'Coloquei tudo em cima, começa escrever e não parei mais', 'Meu pai me chamava de galinha,qnd me via conversando com meus amigos,me tocou de casa mas depois voltamos a nos falar,sempre ajudei ele,no finale pediu perdão', 'Não consigo prosperar,fico andando em círculos, endividada,mas com sonho grande', 'Não', '10', 'Até R$ 2.000', 'Não tenho condições de investir', 'Aqui na aliança divergente', NULL, NULL, '[{"nome": "TRAVA DO SERVIDOR", "score": 8}, {"nome": "TRAVA DA VÍTIMA", "score": 7}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 6.2}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 6}, {"nome": "TRAVA DA ESCASSEZ", "score": 5}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 4.4}, {"nome": "TRAVA PATERNA", "score": 3.6}, {"nome": "TRAVA DO AMBIENTE", "score": 3}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 2.8}, {"nome": "TRAVA DA APROVAÇÃO", "score": 2.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

