INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('H38cnpfjnGBE9JOCx8DU', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-04-27T20:17:00.858Z'::timestamptz, 'Marilza Batista', 'maba-9000@hotmail.com', '67992764726', '52', 'Fisioterapeuta', 'Bom, eu tive uma infância muito difícil, eu sou a filha mais velha do casal que tem 6 filhos 5 mulher e um menino desde o meu e 5 anos eu tive que cuidar do meus irmãos 9 anos saí da casa dos meus pais para cuidar do filho dos outros e desde então passei por várias casas trabalhando de doméstica. Empregada sendo humilhada. 1 17 anos fui internado no hospital de doido e saí de lá sozinha com a ajuda de Deus perdi o chão as pessoas que eu confiava ali, eu vi meu mundo desmoronar. Meu pai minha mãe nunca superaram me dá carinho sempre for só cobrança muita surra eu apanhava por tudo se meus irmãos faziam as coisas erradas eu apanhava que se ele brigava com a minha mãe eu apanhava quem me protegia era meu avô pai do meu pai mas com 8 anos Isso 8 anos meu avô morreu faleceu aí eu tinha um tio irmão da minha mãe que também me ajudava me dava presente, me dava roupa balinha, porque meu pai não me dava nem balinha, eu sempre tinha que vestir resto dos outros eu perdi também esse meu tio meu irmão foi pra mim como se fosse. Meu filho quando eu fiz 18 anos. Meu irmão faleceu pra mim foi foi muito difícil também aí eu tinha meu irmão que eu era muito apegada a ela também e em 2020 ela faleceu e em 2018 Em  eu entrei na menopausa acabou meu ciclo menstrual menstrual então Então aquilo ao sonho de ter uma família de ter filho acabou e daí em seguida perdi a minha irmã então perdi a vontade de fazer as coisas, fiquei 3 anos sem fazer um nada na minha casa. Só pensava em vendê-lo disfazê-la, tentei várias formas de fazer e até agora não consegui hoje eu me encontro numa situação que eu tento estudar nada, então na minha cabeça tento tudo tá muito difícil até um filme que eu assisto eu não consigo entender nada eu tô vendo as coisas passada na minha frente. Sem sentido nenhum', 'Tá bom como eu já disse na minha adolescência, né, eu já trabalhava tive sempre muita responsabilidade, fui internada no hospital de doido vi meus minha vida desmoronar, ali eu descobri que eu era sozinho e que eu não tinha ninguém que se tinha alguém por mim era só eu às vezes eu. O.', 'A minha vida de adulta foi muito trabalho, continuou muito trabalho muita luta muita dificuldade pra conseguir as coisas. Hoje eu tenho uma casa, não acabada uma profissão que eu não consigo tirar mais de um salário mínimo, não consigo captar paciente vivo sozinha.', 'Não se não consigo especificar qual problema emocional gostaria de resolver hoje porque como eu disse, hoje eu tô vendo a vida passar na minha frente, nada pra mim tem sentido.', 'Não', '10', 'Até R$ 2.000', 'Não tenho condições de investir', 'No grupo regional do Mato Grosso do Sul das aliadas', NULL, NULL, '[{"nome": "TRAVA DO SERVIDOR", "score": 7.6}, {"nome": "TRAVA DO AMBIENTE", "score": 6.4}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 6.2}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 5.8}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 5.6}, {"nome": "TRAVA DA VÍTIMA", "score": 5.4}, {"nome": "TRAVA DA ESCASSEZ", "score": 4.6}, {"nome": "TRAVA PATERNA", "score": 4.6}, {"nome": "TRAVA DA APROVAÇÃO", "score": 2.8}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 2.8}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
