INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('Qlp4PNz0m2xWKLIVoIm4', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-04-27T20:38:05.242Z'::timestamptz, 'Marilza Batista', 'maba-9000@hotmail.com', '(67) 99276-4726', '52', 'Fisioterapeuta', 'Infância foi muito difícil eu sou a primeira filha um casal que tem 6 filhos sendo 5 mulheres e um rapaz desde 5 anos tive que cuidar dos meus irmãos  8 ano perdi o avô Com O9 eu perdi o meu tio que também me apoiava, me ajudava que comprava roupa para mim que meu pai só dava roupa para meus irmãos eu tinha que vestir os resto dos outros e como aviam, também. Eu tive que sair de casa pra começar cuidar do filho dos outros, passando por várias casas sendo babá e filho dos outros.', 'Minha adolescência continuei trabalhando com os outros ajudando meus pais meu salário todo eu dava para ajudar na despesa da casa dos meus pais mesmo nao morando com eles eu sempre ajudei Com 17 anos foi internado no hospital de doido e ouvi o meu mundo se acabar', 'Sair do hospital de doido com a graça de Deus porque meus pais não foram tirar eu de lá e vim embora pra Campo Grande aqui pra tem Campo Grande passeio por várias humilhação orando na casa dos outros muitas dificuldades muitas noites sem a comida, mas nunca precisei dormir na rua. Sempre que encontrei alguém que me desse abrigo por uma noite hoje tenho uma casa mal acabado as pessoas que eu mais gostava que eu acreditava que podia conversar comigo morreram com 2020 e eu tinha o meu irmão aqui a gente era muito ligado. Ela também se foi hoje eu me encontro sozinha num casei, não tenho filhos, tenho uma casa mal acabada, que eu não tenho vontade de terminar, já fiz de um tudo pra desfazer, mas não consigo também desfazer comprar uma menor fisioterapeuta, mas não consigo fazer mais que um salário mínimo minha vida. É muito solitária não saio muito não tenho amigos também não tenho inimigos vejo hoje enquanto a vida passar na minha frente não sinto nada nada pra mim tem sentido', 'Problema em mocional hoje seria isso que eu não tenho não vejo sentido na vida não tenho sonho não tenho desejo não tenho expectativa não o mesmo nada', 'Não', '10', 'Até R$ 2.000', 'Não tenho condições de investir', 'No grupo regional do Mato Grosso do Sul das aliadas', NULL, NULL, '[{"nome": "TRAVA DA PERFEIÇÃO", "score": 6.4}, {"nome": "TRAVA PATERNA", "score": 6.2}, {"nome": "TRAVA DA VÍTIMA", "score": 4.6}, {"nome": "TRAVA DO AMBIENTE", "score": 4.6}, {"nome": "TRAVA DA ESCASSEZ", "score": 4.4}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 2.8}, {"nome": "TRAVA DA APROVAÇÃO", "score": 2.8}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 2.8}, {"nome": "TRAVA DO SERVIDOR", "score": 2.8}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 2.8}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
