INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('vZGHddkmqxC333N4F2ex', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-04-27T23:15:09.767Z'::timestamptz, 'dirleia patricia monteiro paes', 'drapati.paes@gmail.com', '67991343213', '46', 'Massoterapeuta, estudante de medicina', 'Na minha infância eu não lembro de muitas coisas me lembro do meu pai tá passando por mim eu devia ter uns dois anos de idade a minha mãe fala que não sabe como eu lembro disso eu me lembro de um namorado que ela teve e então toda vez que eu sinto cheiro de cocô de boi Eu lembro dessa pessoa que era namorado dela a minha mãe bebia muito ficava endemoniada eu vivi muito na casa das pessoas fui criado por uma madrinha e por pessoas estranhas apanhei muito de pessoas que eu não conhecia quando eu tinha 6 anos de idade eu tive abuso sexual também fui abusada mas não me lembro de foi consumado quando criança eu sempre ouvi muito que eu não nasci no beiço de ouro que aquilo não era para mim que eu tinha espírito de rica mas eu tinha nascido pobre então eu sempre ouvi muito isso quando criança não fui criada com meu pai fui conhecer meu pai já com 24 anos de idade eu fui criada por um padrasto quando minha mãe se casou quando eu tinha 10 anos essa pessoa era muito violenta com a minha mãe batia muito nela bebia e então só essas coisas que eu lembro da infância.', 'A minha adolescência eu com 12 anos fugi de casa fui trabalhar então desde os meus 11 anos de idade as pessoas achava que eu já não era mais moça que eu fui muito danada fui muito danada muita arteira muito mentirosa eu tinha uma imaginação incrível então as pessoas nunca acreditavam quando eu falava a verdade e eu perdi minha virgindade com 16 anos para 17 e 4 meses depois eu já virei garota de programa fiquei nessa vida por uns 4 anos essa foi a minha adolescência', 'Com 18 anos eu tive um namorado Eu namorei por 6 anos foi a melhor época da minha vida era uma holandês uma pessoa fantástica mas chegou um dia acabou o nosso sentimento e nós nos separamos eu voltei para o Brasil eu morava fora do Brasil e 6 meses depois eu conheci meu marido casei foram 15 anos de um casamento de muita violência onde eu apanhei muito ele era uma pessoa muito obsessiva controlador enfim me estuprava quase que diariamente me batia inclusive me bateu na minha gravidez aonde eu tenho um filho especial em 2013 eu perdi a minha madrinha ele tinha me proibido de visitá-la então isso me marcou muito e eu fiquei estado de depressão tentei suicídio só não concluir porque meu filho chegou e me pediu uma criança especial me pediu de fazer isso e em 2017 depois que de tanto apanhar quando ele tá tentando me matar eu para me defender acabei matando ele hoje eu respondo por isso estou em prisão domiciliar os tornozeleiras desde outubro e a minha vida não tem sido fácil e eu quero mudar e eu não sei como a procrastinação assim é demais da conta eu tento tento mas eu não consigo movimentar fazer fluir as coisas', 'Eu quero resolver a procrastinação eu quero resolver esse sentimento de culpa eu ter fingir minha vida mas por ter defendido a minha vida eu fui julgado e fui culpada e sumir profundamente', 'Sim vários', '10', 'Até R$ 2.000', 'Depende', 'Foi num grupo da aliança divergente', NULL, NULL, '[{"nome": "TRAVA PATERNA", "score": 10}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 10}, {"nome": "TRAVA DA VÍTIMA", "score": 8.4}, {"nome": "TRAVA DO SERVIDOR", "score": 8.4}, {"nome": "TRAVA DA APROVAÇÃO", "score": 7.8}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 7.8}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 6}, {"nome": "TRAVA DO AMBIENTE", "score": 6}, {"nome": "TRAVA DA ESCASSEZ", "score": 5.8}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 4.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('H1gtTUbCPS7Vy1mljxwp', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-04-28T01:43:51.834Z'::timestamptz, 'Diane Martins Ferreira', 'daimartinsrh6@gmail.com', '12988168174', '40', 'Administradora', 'Minha mae nunca foi feliz no casamento não queria filhos mas acabou tendo 3, meu pai bebe e isso a irritava muito, sofri abuso leve do meu irmão e de um vizinho. Minha mae teve cancer', 'Meu namorado morreu na minha frente quando tentaram assaltar a moto dele como saia muito era abusada e tinha muitas relações.', 'As falas da minha mae eram bem duras me desabafando, como saia muito e n tinha relacionamento fixo', 'Quero conseguir progredir sem me afundar em dívidas, quero ter um relacionamento saudável', 'So piscicologa', '10', 'De R$ 2.001 a R$ 5.000', 'Não tenho condições de investir', 'Grupo whatsapp', NULL, NULL, '[{"nome": "TRAVA DA PERFEIÇÃO", "score": 7}, {"nome": "TRAVA DA APROVAÇÃO", "score": 6.8}, {"nome": "TRAVA DA VÍTIMA", "score": 6.6}, {"nome": "TRAVA DO SERVIDOR", "score": 6.6}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 6.4}, {"nome": "TRAVA DA ESCASSEZ", "score": 6}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 6}, {"nome": "TRAVA DO AMBIENTE", "score": 6}, {"nome": "TRAVA PATERNA", "score": 5.8}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 5.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('onP3iQPAmUX3nsg7htrF', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-05-04T00:42:26.659Z'::timestamptz, 'Suely cristina ribeiro', 'suely.cristina.ribeiro41@gmail.com', '1194320360', '57', 'Estudante', 'Tem momentos meu pai batia em.minha mãe minha mãe revidava , iitas brigas,  meu pai alcooatra, abuso tentativa de estrangulamento,  um homem me pegou 5 anos eu gritei depois no tinha mais voz mais uma mulher escutou vou atrás do muro  não sei oque ela falou ele siu correndo .houve separação eu com 9 anos fiquei com meu pai.', 'Abuso por mulher  a madrinha de minha irmã recebia entidade que er homem me beijava na boca , meu pai sempre falava que amava , meu vizinho dirido bêbado matou 6 pessoas foi horrível os comentários  mor perto trilho de trem sempre tinha um morto que tentava atravessar parava udo pequena era curiosa .', 'Minha arrasta raia meu pai com melhor amigo dele ele também batia nela mais não sabia , meu pai bêbado caído no quintal , ele não deixava amigos ir em casa , e sai de casa , forçada por este motivo batinela ela tentava me matar', 'Baixa estima', 'Faço terapia', '8', 'Até R$ 2.000', 'Não tenho condições de investir', 'Uma linda divergente', NULL, NULL, '[{"nome": "TRAVA DA ESCASSEZ", "score": 10}, {"nome": "TRAVA DA APROVAÇÃO", "score": 10}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 10}, {"nome": "TRAVA DO SERVIDOR", "score": 9.4}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 9.2}, {"nome": "TRAVA DO AMBIENTE", "score": 8.6}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 8}, {"nome": "TRAVA PATERNA", "score": 8}, {"nome": "TRAVA DA VÍTIMA", "score": 7}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 6.8}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('5XvI2YqUHtghZQ0jit1J', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-05-05T17:42:00.839Z'::timestamptz, 'Edinalva Alves de Oliveira', 'tikasorriso@gmail.com', '66999999533', '56', 'Costureira', 'Minha irmã  que cuidava de mim fugiu com o namorado, me senti só  pois dormiamos juntas e fiquei dormindo sozinha na sequência acordei uma noite com meu irmao mabdando eu ficar quieta  e se esfregando em mim, a parti4 dali achei que eu nao prestava , pois sempre ouvi  as mulheres mais velhas dizendo que moca que nao fosse virgem nao prestava e eu nao sabia o qye realmebte havia acontecido ali pra minha cabeca de 9 anos eu nao era mais virgem. Meu avo faleceu. Meu pai faliu, meu avo vendeu 9 sitio tivemos que nos mudar do lugar onde eu nasci e vivi ate os nove  a dez anos, una coisa que me marcou que senti muito foi uma prima falar da minha roupa que meu chort nao era chort era calção isso mexeu comigo tambem.', 'Meu irmao 2 anos mais velho que eu, comwcou a me bater oor nada e me batia muito, maltratava minhas amigas que ia la em casa pra brincar. Não  lembro de ele ser ruim comigo antes so depois que nos mudamos de lugar depois da falência do meu pai , ai moramos embaixo de uma lona. Ate construir a casa sentia muuta vergonha, pois anteriormente  a gente era bem de vida e depois morava num barraco me sentia mau com os colegas de escola só com alguns,  4 anos depous nos mudamos de estado,outro irmaobque ey gostava muito faleceu aos 18 anos dele, senti muito por isso.  E meu irmao que me batia  continuou me batendobe sendo ruim comigo, aos 15 namorei um cara mais velho com a permissao dos meus pais 8 meses depois eu engravidei e ele me deixou. Queria que eu tomasse uma injecao para abortar eu nao tomei ele sumiu, ai fiz coisas que nao me orgulho mas tambem na época nao me senti mau , 1 dia meu pai gritou comigo eu estava grávida  ai fugi de casa encontrei uma pessoa que so me usou uns dias e me abandonou. Meu pai me buscou de volta  e eu voltei continuei apanhando do meu irmão.  Minha filha nasceu o pai dela nunca pediu para ve la. Seguiba vida de morar na rica fomos pra cidade tinha parado de estudar na sexta série. Pq fomos morar no mato.', 'Passou quase tres anos encontrei  uma pessoa , que quis ficar comigo pq antes encontrava alguns quebate dizia que a familua nao permitiria que ficassem com uma mae solteira eu sentia que so queriam me usar pois eu nao era boa suficiente pra ninguem né, vafinal eu nao prestava,  nao era virgem. Quando me juntei com meu marido nos mudamos de cidade para longe de onde morava e perto da familua dele e sempre ouvi do meu sogro coisas que me levavava pensar que eu nao era boa paravaquela familia, foram 10 anos tuve mais 2 filhos e um dia meu sogro ameacoy meu marido com uma faca e dissebpra ele quebele tinhavtransformadona casa dele em um bordel a briga foi feia mas a partir da8 nao miramos mais juntos na mesma casa comnos sogros acheivque aquilo tinha sido bom, pelo aumenos isso estava decidido, voktamos a morar na antiga cidade numa casinha cedida pelos meus pais, onde moro ate hj', 'Enfim tenho ansiedade, tenho pensamentos , melancolicos, sai feridas na pele periodicamente , nao consigo me sentir adulta pra tomar a decisao de ticar um projeto que tenho pra frente de fazer roupas fitnes para vender, parece que nao vou vender se eu fizer. Mas eu faco consertos de roupas , fiz unhas por conta por 19 anos sei que sou capaz mas nao sou segura nao indentifico o que me trava', 'Nao', '9', 'Até R$ 2.000', 'Não tenho condições de investir', 'Numa comunidade do WhatsApp', NULL, NULL, '[{"nome": "TRAVA DA COMPETÊNCIA", "score": 8}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 8}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 7.6}, {"nome": "TRAVA DA APROVAÇÃO", "score": 7.6}, {"nome": "TRAVA DA VÍTIMA", "score": 7.2}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 7.2}, {"nome": "TRAVA DA ESCASSEZ", "score": 7}, {"nome": "TRAVA DO AMBIENTE", "score": 7}, {"nome": "TRAVA DO SERVIDOR", "score": 6.8}, {"nome": "TRAVA PATERNA", "score": 5.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('sWJGl2ajTc2c2HXmnbmx', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-05-10T22:44:49.195Z'::timestamptz, 'Glaucia gramusk paixão de carvalho Korontai', 'glauciakorontai@gmail.com', '41991881213', '45', 'Do lar', 'Meus pais passaram por separação, mas eu já tinha saído de casa, eu casei com o pai da minha filha com 14anos. Tive uma infância com muita dificuldade financeira.', 'Eu casei com o pai da minha filha com 14 anos, sofri muito com traição e ele me batia. Quis casar cedo, pois achei que poderia ter mais liberdade, pois eu queria sair, curtir a vida e meus pais eram muito severos.', 'Sofri muito no meu primeiro casamento, nos separamos depois de 13 anos. Comecei a namorar homens mais velhos. Vi que homens da minha idade não queria nada serio. Namorei um homem casado na minha cidade, durou 5 anos. A mulher dele descobriu e terminamos. Eu queria muito um relacionamento sólido, saudável, eu estava nesse relacionamento mais ao mesmo tempo não queria estar, pq eu sabia que era errado está com um homem que já era casado. E procurei sempre me relacionar com alguém que eu visse que poderíamos ter um futuro próspero na vida financeira. Sempre tive medo de não ter condições o suficiente para dar uma boa vida pra minha filha e minha mãe. Na época eu só pensava em ter uma vida financeira boa. 
Morava no Piauí, estou aqui há quase 15 anos, conheci meu esposo hoje em joinville, pois eu morava lá.  Tenho um casamento maravilhoso, um esposo muito, muito bom. Só que estamos em dificuldades financeiras e isso está afetando nossa saúde. Estamos casados a 7 anos.', 'Nesses últimos anos, venho tento crise de pânico, medo de morrer, saúde algumas questões que começam e aumentam. Meu esposo também. Ele tem uma capacidade de começar grandes negócios, mas não se materializa. Ele tem uma empresa, o que no momento está dando mal pra pagar o aluguel. Quando casamos ele disse que não precisava eu trabalhar fora, que ele queria uma esposa, pra auxiliar ele em casa e era justamente o que eu queria também. Eu sempre quis ser esposa, cuidar do marido, da família, da casa. Só que por esses últimos meses tive que trabalhar fora, pra da um suporte pra ele. Só que é o que nós não queríamos. É uma longa história. Meu marido tem uma pequena empresa, mas dá mal pra pagar a secretaria, ele não tem como mandar ela embora. Pois não tem como pagar os direitos dela. O que sobra mal da pra comer, aluguel atrasado, um caos. Tomo floral pra ajudar na ansiedade e pânico, não gosto de tomar remédio forte. Sem falar que não consigo emagrecer,estou a cima do peso.', 'Já fizemos muitos, já comprei vários cursos. Me individei. Por último estou na Aliança', '10', 'De R$ 2.001 a R$ 5.000', 'Sim, estou disposto a investir pois preciso mudar.', 'A Sandra uma amiga e vizinha me indicou voce', NULL, NULL, '[{"nome": "TRAVA DA COMPETÊNCIA", "score": 10}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 9.6}, {"nome": "TRAVA DA APROVAÇÃO", "score": 9.2}, {"nome": "TRAVA DA VÍTIMA", "score": 9.2}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 9.2}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 8.4}, {"nome": "TRAVA DA ESCASSEZ", "score": 8}, {"nome": "TRAVA PATERNA", "score": 7.2}, {"nome": "TRAVA DO SERVIDOR", "score": 7.2}, {"nome": "TRAVA DO AMBIENTE", "score": 6.6}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('faZMi7R1yw5dhMDMqYaC', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-05-11T12:54:35.126Z'::timestamptz, 'GISLAINE LASKA DOS SANTOS', 'gislainelaska@hotmail.com', '41996751205', '46', 'Autônomo', 'A minha infância ela foi marcada por falta de dinheiro mas isso não era um eu não via isso como uma tragédia era a vida que eu conhecia né eu me senti isolada eu tenho mais três irmãos e sempre via minha mãe trabalhando muito meu pai assim trabalhava mas não tinha uma presença muito constante e eu lembro de com sete oito anos eu já cuidava de dois menininhos assim cuidar como babá não mas eu servia para ficar com eles né como se fosse uma babá mas não era eu não tinha muitos amigos mas eu era estudiosa eu gostava de ir para aula e da minha primeira infância assim até o 7 anos eu não lembro muita coisa do zero né eu começo a lembrar a partir do momento que eu fui para escola entendeu eu lembro de catequese escola amigos de escola se eu não tinha muito eu lembro que eu comecei a perceber a diferença social assim de quem tem quem não tem dinheiro quando eu fui para escola antes eu não lembro realmente e assim brincava bastante eu lembro que eu brincava sozinha essas coisas assim não foi traumático de relacionamento assim nunca vi meus pais brigarem sempre foi um casal que os dois trabalharam a minha mãe sempre cuidou da família então não tem nada traumático em relação aos meus pais.', 'Então minha adolescência dos 13 aos 18 anos digamos assim é dos 13 aos 17 e eu ainda Aproveitei assim Ia para a aula ficava em casa depois do almoço brincava ia para catequese foram momentos bons a nossa vida já começou a melhorar um pouco ainda a gente mudou de casa mas ainda a realidade social ainda era ruim com 17 anos eu comecei a trabalhar né fora então daí já amadureci um pouco mais fui trabalhar como vendedora Foi algo que marcou assim porque eu comecei um pouco de independência financeira né mas foi um período bom assim tinha muitos amores platônicos não namorava mas eu brincava bastante assim jogava bastante vôlei foi um período de conhecimento não teve nada assim de separações falecimentos não era Trabalho estudo continue estudando né terminei o ensino médio e é isso foi quando eu iniciei meu né que eu fui trabalhar numa loja eu era bem tímida era magrinha tinha alguns amigos foi um período bom.', 'Bom minha vida adulta começou a partir do momento eu acho que eu comecei a trabalhar com 17 anos né foi quando eu comecei a perceber que o mundo era diferente do que eu tinha em casa aí comecei a trabalhar com 17 na loja com 20 anos eu 18 anos eu comecei a trabalhar num banco e com 22 O que foi mais marcante foi a perda do meu pai que ele faleceu daí a partir daí a minha vida começou a tomar um diferente né eu comecei a estudar sair do banco onde eu trabalhava eu trabalhei por cinco anos lá fiz o vestibular passei para faculdade minha mãe me ajudou a pagar Minha Faculdade de Letras terminei a faculdade com 206 27 anos comecei a trabalhar como professora porque eu me formei letras conheci meu marido em relação a vida amorosa foi um caos né Foi bem complicado porque eu sempre tava com pessoas que não me valorizavam tipo assim não combinava sabe e eu sempre tive uma vida amorosa meio frustrante assim aí eu conheci meu marido com 26 anos a gente namorou por 4 anos aos 31 eu casei com ele que vem morar junto com ele 32 aos 31 Eu perdi o meu primeiro filho aí engravidei já no mesmo ano né No ano seguinte com 32 tive meu segundo filho que hoje tá com 13 anos eu parei quando meu segundo filho nasceu eu parei de trabalhar fora para cuidar dele para aproveitar a gestação e a primeira infância dele e hoje ele tá com 13 anos eu com 46 tô vivendo todo um processo de vida ainda tô numa fase assim que eu tô acima do peso Tô frustrada tô sem dinheiro às vezes eu me vejo repetindo a história da minha mãe e do meu pai então eu tô num momento de mudança onde eu tenho capacidade de fazer as coisas mas o dinheiro não entra eu sofro muito com medo de perder as pessoas que eu amo enfim', 'Eu gostaria de resolver essa minha dependência emocional que eu tenho das pessoas é o fato de não me valorizar o suficiente a minha questão financeira Por que que eu não consigo ganhar o dinheiro suficiente para manter a vida que eu quero porque que eu sempre tô atrás assim e sempre parece que tá faltando alguma coisa porque que eu não consigo ser amada de uma maneira recíproca sabe porque eu dou muito amor eu sou uma pessoa carinhosa atenciosa gentil e nem sempre eu recebo sem troca eu sei que as pessoas percebem mas eu sei que eu não sou amada talvez não do jeito que eu queira ser amada entendeu Eu queria ter uma vida mais leve mas produtiva não gostar mais de mim cuidar mais na minha saúde e realmente o financeiro é o que mais pega assim eu não sou uma pessoa miserável mas também não tenho tudo que eu quero e sempre tô me sentindo inferior das pessoas em relação ao dinheiro não intelectualmente ou fisicamente Lógico que eu tô acima do peso tudo mas é uma questão de ter cabeça e corpo para cuidar assim melhor do meu corpo mas problemas que eu realmente queria resolver era o financeiro e o meu relacionamento em relação ao meu casamento', 'Não de conversar com terapeuta fazer psicólogo essas coisas não', '10', 'De R$ 2.001 a R$ 5.000', 'Não tenho condições de investir', 'Eu vi a aliança divergente na internet pelo pelo Instagram e comecei ver alguns vídeos do YouTube e daí eu fiz a minha inscrição e eu tô na Aliança desde Junho do ano passado vai acabar meu contrato agora Junho deste ano né e provavelmente eu não vou conseguir renovar porque eu não tenho os 250 para pagar todo mês e eu não tô conseguindo fazer as coisas que a aliança propõe eu consigo enxergar as coisas eu sei o que que tá acontecendo eu enxergo as manipulações eu enxergo os padrões o que que precisa ser feito mas eu não consigo fazer eu não tenho forças assim eu já percebi tudo as minhas amarras os meus medos só que para não magoar as pessoas ou para não me distanciar das pessoas eu não consigo fazer o que a aliança propõe', NULL, NULL, '[{"nome": "TRAVA DA VÍTIMA", "score": 8.8}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 8.4}, {"nome": "TRAVA DO SERVIDOR", "score": 8.2}, {"nome": "TRAVA DA APROVAÇÃO", "score": 7.6}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 6.6}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 6}, {"nome": "TRAVA DO AMBIENTE", "score": 5.6}, {"nome": "TRAVA PATERNA", "score": 5}, {"nome": "TRAVA DA ESCASSEZ", "score": 4.6}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 1.4}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
