INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('2AuJw8AvoDt5AAoy76FC', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-05-26T16:04:56.270Z'::timestamptz, 'Claudia Maria Alves Marques', 'claudia.naja8@hotmail.com', '51985182959', '62', 'Designer de criações em tecido, roupas e cases', 'Minha infância foi traumática, como a maioria da minha idade. Pai alcoolista, mãe aparentemente vulnerável e uma irmã 19 anos mais velha, que dava conta do meu sustento e de minha mãe, ela foi a representação da força. Muitas raivas e medos, aos 05 anos tive a perda de um amiguinho de prédio, que era como um irmão mais novo. Tenho a sensação que a partir deste fato, foram acontecendo muitas perdas. Muitos abusos psicológicos. Aprendi a ceder, para me livrar de conflitos', 'Fui uma adolescente muito rebelde, logo estava inserida em grupos que atuavam no bem estar de crianças e mulheres. Meu pai morreu quando eu tinha 15 anos e minha mãe quando eu tinha 18.', 'Cheguei na vida adulta quando minha mãe morreu. Fui morar com meu namorado, porque não queria ir morar com minha irmã, pareciam mundos completamente distintos. Hoje eu entendo que queríamos o mesmo, apenas formas diferentes de enxergar o mundo. Fiquei grávida aos 19 e ganhei meus filhos gêmeos aos 20. Um casal. Me separei após 07 anos. Casei novamente por mais 08 anos, tive meu terceiro filho. Uma experiência que me trouxe muita paz. Depois casei novamente por mais 04 anos. Após isto fiquei 08 anos sozinha, depois tive um romance que foi o céu e o inferno ao mesmo tempo, aprendi a me conhecer e não mais esconder meus sentimentos. Hoje vivo bem sozinha. Dos 26 aos 44 trabalhei em TI, ganhava muito bem, era uma ótima profissional. Quando os gêmeos estavam com 27anos começou o problema com as drogas. Ai meu mundo desmoronou, mas continuei firme, coloquei os dois em tratamento, foram 02 anos lutando e um casamento que não aguentou a situação. Neste momento larguei a TI e aí iniciou um caminho de apertos financeiros, vendi meu carro, ainda bem que já tinha adquirido meu apto, pago à vista. O apto que moro hoje.
Como eu sempre costurava/mudava minhas roupas. Fui trabalhar na loja de uma amiga, fazendo os consertos das roupas. A partir daí fui fazer cursos de costura/modelagem', 'Ainda tenho restrição financeira, tenho capacidade, tenho clientes, meu único empecilho sou eu mesma. Hoje percebo meu valor, mas ainda tenho gravado no meu corpo as crenças da criança . Desde os 18 anos iniciei um processo de auto conhecimento, muitas terapias, psicanálise, reich, constelações, neurociência, terapia comportamental …', 'Sim', '10', 'De R$ 2.001 a R$ 5.000', 'Não tenho condições de investir', 'Na Aliança Divergente', NULL, NULL, '[{"nome": "TRAVA DA APROVAÇÃO", "score": 6.8}, {"nome": "TRAVA DO SERVIDOR", "score": 6.4}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 6.2}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 5.6}, {"nome": "TRAVA DA ESCASSEZ", "score": 5}, {"nome": "TRAVA DA VÍTIMA", "score": 5}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 4.6}, {"nome": "TRAVA PATERNA", "score": 4}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 2.6}, {"nome": "TRAVA DO AMBIENTE", "score": 2.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
