VALUES ('zqrYZ3WDkUrggji2uR2Q', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-06-08T17:49:47.137Z'::timestamptz, 'Loredana Flauzino', 'loredanaflauzino@yahoo.com', '16999723134', '52', 'Fonoaudióloga', 'Minha mãe exigia muito de mim. Era como se nada ficasse bom ou eu nunca era suficiente! Perdi meu pai aos 23 anos, morreu na minha frente!', 'Dificuldade de dizer não, de buscar aprovação, minha mãe muito boa e dedicada mas não era afetiva! Meu pai morreu na minha frente quando eu tinha 23 anos, éramos muito ligados, fiz de tudo para reanimar mas ele partiu', 'Dificuldade por auto estima baixa! Nunca achava que encontraria o homem dos meus sonhos! Me casei mais para sair do autoritarismo de meus pais… mas acabei me colocando em um casamento tóxico, abusivo, narcisista e futuramente sofri violência doméstica, física, psicológica, patrimonial….. quando tive coragem de divorciar por minha família ser contra separação, o grupo da igreja dizia que eu era anticristo e vagabunda se destruísse um casamento… mas com muita luta me separei, mas há 8 anos ele me ataca judicialmente! E desenvolvi há 2 anos câncer de mama e mudou pra pior tudo em minha vida profissional, financeira, pessoal…..', 'Depressão e pânico 
Culpa, medo, paralisação 
Prosperidade financeira 
Qualidade de vida
Ter qualidade de tempo com meus filhos
Encontrar um homem leal, provedor, leve, carinhoso, divertido, bem resolvido financeiramente e emocionalmente', 'Sim! Psicoterapia por muitos anos', '10', 'De R$ 2.001 a R$ 5.000', 'Depende', 'Grupo WhatsApp Aliança Divergente', NULL, NULL, '[{"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 9.6}, {"nome": "TRAVA DA ESCASSEZ", "score": 9.4}, {"nome": "TRAVA DA APROVAÇÃO", "score": 9.4}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 9.2}, {"nome": "TRAVA DO SERVIDOR", "score": 9.2}, {"nome": "TRAVA DO AMBIENTE", "score": 8.8}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 8.6}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 8.4}, {"nome": "TRAVA DA VÍTIMA", "score": 8.2}, {"nome": "TRAVA PATERNA", "score": 6}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('ngSNytbwKA2bsWddvh2n', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-06-14T00:11:13.877Z'::timestamptz, 'Alsisa De Oliveira Zanco', 'lc_al_oz@hotmail.com', '11988629980', '68', 'Aposentada', 'Não tive infância. Até os meus 7 anos, eu tinha uma dor de cabeça muito forte; enquanto as outras crianças brincavam lá fora, eu tinha que ficar no quarto escuro, pois não podia ver luz. Aos 9 anos comecei a trabalhar de doméstica em uma casa, minha família era muito pobre e na maioria das vezes não tínhamos o que comer , fiquei nessa casa até os 18 anos.', 'Não tive adolescência. Na casa em que eu trabalhava, sofria muita humilhação, as vezes ela me agredia fisicamente com beliscões, no dia em que fiz 18 anos, ela me bateu. Eu cuidava da mãe dela também, e quando a mãe faleceu, ela me mandou embora.', 'Minha vida adulta, não mudou muito, nós morávamos em uma fundação, e umas das mulheres que trabalha lá, me arrumou um serviço em Curitiba, e eu fui pra lá, aí melhorou, pois já não sofria mais humilhações. Saia da onde eu trabalhava, que era uma pensão para estudantes, eu era cozinheira e fui pra outra casa onde eu cuidava também de um bebê. Um dia passei mal e fui ao médico, me deram anestesia geral e eu fiquei horas lá, quando voltei, a mulher me dispensou. Fiquei sem saber pra onde ir, falei com uma colega e ela me indicou uma pensão. Arrumei um namorado, acabei engravidando, eu estudava e uma colega de escola me convidou pra morar com ela, pois não tinha dinheiro pra pagar a pensão. Fiquei uns dias lá, ela queria dinheiro e eu não tinha, ela me mandou embora, arrumei um quartinho, dormia no chão e comia pão duro com aguá, meu namorado me abandonou, foi quando eu criei coragem e escrevi para os meus pais avisando que eu iria pra casa. Detalhe; quando eu tinha 11anos anos, eles foram embora pro Paraná e me deixaram com aquela senhora. Bom voltei, me receberam bem, minha percebeu que eu estava grávida, fui bem aceita, tive meu filho, ele ainda bebê deixei com meus pais e fui  com minha irmã pra SP trabalhar, sofri horrores com ela. Enfim minha vida adulta não mudou muito,sempre trabalhando em casa de família, engravidei novamente, já trabalhava como técnica em turismo na prefeitura de Bebedouro, morava sozinha, tive meu filho, sofri perrengues, pois fui dispensada do serviço, voltei pra SP, fui morar com outra irmã, voltei a trabalhar como doméstica, encontrei um ex namorado que foi o amor da minha vida, fomos morar juntos, sofri muito, pois ele tinha um ciúmes doentio, mas ficamos 20 anos juntos, casamos, um ano depois ela faleceu e me deixou muito bem amparada. Eu que não soube administrar o q ele me deixou. Mas estou bem, tenho casa pra morar.', 'O abandono dos meus pais, por que me deixaram pra trás qd foram embora pro PR; pq tantas humilhações; pq esse padrão se repete tanto. Tenho 68 anos, mas sinto que não cresci. Por que  minha mente é limitada?', 'Não', '10', 'Até R$ 2.000', 'Não tenho condições de investir', 'No Whatzapp', NULL, NULL, '[{"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 9.8}, {"nome": "TRAVA DA VÍTIMA", "score": 8}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 6.6}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 6.4}, {"nome": "TRAVA DO SERVIDOR", "score": 6}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 5.8}, {"nome": "TRAVA DA ESCASSEZ", "score": 5.4}, {"nome": "TRAVA DO AMBIENTE", "score": 5.2}, {"nome": "TRAVA PATERNA", "score": 5}, {"nome": "TRAVA DA APROVAÇÃO", "score": 4.2}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('qx8n5gqi0XQ3AZF8oX14', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-06-21T19:49:58.573Z'::timestamptz, 'Elisângela Assunção', 'elisassuncaos@gmail.com', '48984947987', '42', 'Assistente de seguro', 'Meu pai agredia minha mãe, meu pai ganhava pouco e minha mãe cuidava da casa, até meus 9 anos, ela decidiu trabalhar fora quando meu pai não deu conta de comprar comida pra casa. Meu pai chamou não gostou e chamou ela de puta, algum tempo depois ela arrumou outra pessoa e deixou do meu pai, meu pai não aceitava, havia chantagens envolvendo meus irmãos e brigas com agressão e ameaças até que meu tio se envolveu e matou meu pai no mês do meu aniversário eu estava completando 12 anos.
Um tio da minha mãe passou a mão na minha bunda eu era bem pequena tipo uns 7 anos eu acho e eu fui estimulada sexualmente desde esta idade por um menino adolescente vizinho nosso.
Meu pai antes dos meu 6 anos bebia muito teve um acidente que deixou ele em coma no hospital por um tempo por conta que estava bêbado e se envolveu numa briga', 'Perdi a virgindade com 13 anos com um traficante e engravidei, e tive uma menina.
Não me dava b com meu padrasto eu queria sair de casa, me juntei com 14 anos com um outro vizinho e fomos morar na casa que era do meu pai. Ele começou a chegar bêbado em casa, terminei com ele, me envolvi com um colega de escola e fui morar com ele, engravidei com 19 anos e tive um menino de uma gravidez muito complicada emocionalmente.
Minha mãe não acreditava na minha capacidade e disse me que eu sonhava alto de mais.', 'Passei necqessidades com este e terminei por engravidar novamente de mais uma menina também uma gravidez complicada emocionalmente.
O pai do 2 filhos mais novos abusou sexualmente da minha filha mais velha , eu denuncie quando descobri e na sequência descobri também que meu irmão participou em algumas ocasiões deste abuso, também denunciei ele e eminha mãe não gostou de eu ter feito isso me falando que ele era muito certinha que estava me fazendo de vítima.', 'Eu quero resolver um problema de fala que eu não consigo ainda ter muito assunto para falar com as pessoas e de carência de parceiro de me sentir completa comigo mesmo', 'Não', '10', 'De R$ 2.001 a R$ 5.000', 'Não tenho condições de investir', 'Grupo de WhatsApp', NULL, NULL, '[{"nome": "TRAVA DA ESCASSEZ", "score": 8.4}, {"nome": "TRAVA DO SERVIDOR", "score": 8.4}, {"nome": "TRAVA DA VÍTIMA", "score": 7.8}, {"nome": "TRAVA PATERNA", "score": 7.6}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 7.6}, {"nome": "TRAVA DO AMBIENTE", "score": 7.4}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 7.2}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 6.8}, {"nome": "TRAVA DA APROVAÇÃO", "score": 6.6}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 5}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('Tm8ByUnwODKyPoy2i0OF', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-06-22T00:33:23.772Z'::timestamptz, 'REJANE LELEI KUSCHEL', 'rejaneleleik@hotmail.com', '45991251607', '54', 'Guarda Municipal', 'Sofri muito abuso físico, psicólogo emocional. Apanhava todos os dias. Fui responsável pela organização e limpeza da casa, desde os 06 anos. Aos 10 anos também era responsável por uma irmã bebê, trocar fraldas, alimentar, não deixar que chorasse. E claro que alguma coisa sempre não ficava bem feita para o meu pai, por isso as surras diárias. E nunca fui defendida das agressões, minha mãe se exímia de qualquer atitude. Até na hora das refeições erra um terror, fazer algum barulho ao mastigar, não conseguir cortar um alimento ou não conseguir engolir por causa do medo e acabar vomitando.', 'Os abusos físicos da infância continuaram na adolescência. E como fui posta em casa de famílias estranhas em uma outra cidade, para terminar os estudos, fazendo do trabalho doméstico o pagamento pela alimentação e um lugar para ficar, não havia limite para o serviço que eu deveria executar e também alguns dos maridos aproveitava para passar as mãos nas minhas partes íntimas. Tempo para estudar realmente, tive bem pouco. Quando ficava doente, gripe, resfriado ou dor estrema nas costas por causa do serviço, os patrões da casa de família daquele momento, me colocava pra rua e, sozinha na rua era obrigada a procurar por outra casa de família, porque meus pais não queriam saber de eu voltar para casa.', 'Aos 19 anos, meus pais mudaram de Estado, cidade e, e minha mãe me obrigou a ir junto para que ela tivesse ajuda com o marido e minhas outras irmãs. Trabalhando fora e cuidando da limpeza da casa, mesmo assim meu pai me batia e xingava, me tratava mal o tempo todo, decidi sair de casa aos 21 anos após uma surra que deixou minha carne rasgada. E por ser submissa, me sentir inferior e tentar agradar, sofri bastante com o desrespeito alheio e abusos emocionais e psicológicos.', 'Quero me libertar da mágoa e da raiva dos meus pais, que travou minha vida em uma depressão crônica de mais de 10 anos. Quero aprender a soltar tudo isso que me machuca e não ficar lembrando o tempo todo da dor. Esse apego ao passado me impede até de querer um relacionamento afetivo.', 'Fiz algumas sessões com psicólogos.', '10', 'De R$ 5.001 a R$ 8.000', 'Depende', 'Indicação de um grupo de whatsapp', NULL, NULL, '[{"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 9.4}, {"nome": "TRAVA PATERNA", "score": 8.4}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 7.8}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 7.6}, {"nome": "TRAVA DO SERVIDOR", "score": 7.6}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 7.2}, {"nome": "TRAVA DA APROVAÇÃO", "score": 7.2}, {"nome": "TRAVA DO AMBIENTE", "score": 7.2}, {"nome": "TRAVA DA VÍTIMA", "score": 6.6}, {"nome": "TRAVA DA ESCASSEZ", "score": 6.4}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

