INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('lspvN9F9EcGdpPbuCc5J', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v1-original', '2026-07-03T03:23:42.254Z'::timestamptz, 'Ana Luiza Bianqui Lins', 'abianquilins@gmail.com', '41996382213', '16', 'Estudante', 'Durante a minha infância, eu era uma criança quieta e calma. Aos 4 anos, mudei da cidade onde nasci, ficando longe do meu pai e da minha mãe, que trabalhava em outro estado. A partir desse momento, passei por diversas mudanças de cidade, permanecendo pouco tempo em cada lugar. Isso fez com que eu não me sentisse segura para criar amizades, pois sabia que logo teria que me mudar novamente. Além disso, também sofria bullying por causa do meu peso e, embora tentasse me defender, isso me afetava.
Outra grande mudança aconteceu quando, aos 10 anos, em 2020, passei a morar com a minha mãe em vez da minha avó, que sempre esteve presente na minha criação. Eu não tinha confiança na minha mãe, pois sentia que não a conhecia de verdade. Com isso, passei a me isolar ainda mais. A pandemia também contribuiu para esse isolamento, já que eu quase não saía de casa. Passei a viver praticamente no tablet, assistindo ao TikTok e conversando com pessoas de diferentes comunidades na internet.
Quando descobri que minha mãe estava grávida, não tive uma reação específica. Apenas fingia que nada estava acontecendo e evitava pensar sobre o assunto. Com o isolamento, apesar das minhas notas eram boas, fui perdendo o interesse pela escola. Também já não me importava em ter amigos na vida real, apenas passava a maior parte do tempo conversando, dia e noite, com pessoas que conhecia pela internet.
Com o passar do tempo, comecei a me sentir incompleta e a ter pensamentos muito negativos, chegando a acreditar que talvez eu não devesse existir. Nesse período, também comecei a desenvolver hábitos prejudiciais para lidar com o que estava sentindo.', 'Quando entrei na pré-adolescência, meu irmão nasceu. Pouco tempo depois, viajei com a minha avó para a cidade onde nasci e permaneci lá por alguns meses. Foi um período muito difícil. Descobriram coisas que eu falava e assistia, o que gerou muitas brigas, pois diziam que eu não deveria conhecer determinados assuntos. Minha relação com meu pai também mudou bastante. Ele deixou de parecer uma pessoa gentil aos meus olhos e a confiança que eu tinha nele praticamente desapareceu.
Durante esse tempo, fiquei sem meu tablet e minha rotina se limitava a estudar e tentar não me envolver em mais problemas. Meus antigos hábitos ainda não haviam desaparecido, eu chorava com muita frequência e cheguei a ter uma crise em que me debatia. O que mais marcou essa fase foi a sensação de exposição. Meu pai contou para a família dele coisas que eu considerava muito íntimas, incluindo segredos e atitudes pelas quais eu já me sentia culpada. Saber que todos conheciam essas partes de mim foi extremamente doloroso.
Quando voltei para casa, o castigo continuou e meu acesso aos eletrônicos ainda era bastante limitado. Minha mãe trabalhava muito, enquanto meu padrasto ficava em casa cuidando do meu irmão. Eu passava boa parte do tempo fazendo minhas tarefas e ajudando com ele, algo de que eu não gostava. Por isso, quando comecei a estudar em uma escola de período integral, senti um grande alívio. Pela primeira vez em muito tempo, eu não me sentia sozinha. Fiz amizades rapidamente, mesmo que muitos desses amigos fossem mais velhos e também enfrentassem seus próprios problemas.
Nessa época, comecei meu primeiro relacionamento. Era um namoro tranquilo, leve e cheio de carinho. Cerca de um ano depois, conheci aquela que se tornou minha melhor amiga. Ela me ajudou a confiar mais em mim mesma e foi uma das pessoas que me incentivaram a começar a desenhar. Pela primeira vez em muito tempo, eu sentia que estava realmente bem. Porém, mais uma vez, precisei me mudar.
Essa mudança foi uma das experiências mais difíceis da minha vida. Meu relacionamento terminou, deixei para trás as pessoas de quem gostava e precisei começar do zero novamente. Na escola nova, descobri que um dos meninos que fazia bullying comigo estudava lá. Curiosamente, algum tempo depois acabamos fazendo parte do mesmo grupo de amigos.
Também me envolvi com duas pessoas que, no fim, não gostavam de mim da forma como eu acreditava. Isso trouxe mais sofrimento e reforçou um ciclo de dor que, naquela época, parecia fazer parte da minha vida.
Hoje, no ensino médio, esse ciclo diminuiu. Algumas amizades chegaram ao fim, mas sinto que minha vida começou a tomar uma direção, embora tudo ainda pareça muito confuso. Essa incerteza desperta bastante ansiedade. Depois que mais um relacionamento terminou, perdi quase toda a vontade de tentar construir algo novamente. Nunca consegui recuperar o interesse pelos estudos e também não sei dizer qual é o meu verdadeiro sonho. Muitas vezes sinto que minhas escolhas são guiadas pela necessidade de agradar as outras pessoas. Ao longo dos anos, fui acumulando essas experiências, e quando tudo parece pesado demais, acabo surtando e sentindo vontade de voltar aos antigos hábitos.', 'Não cheguei a essa fase da vida ainda.', 'Quero diminuir minha ansiedade, e as crises, melhorar minha ideia pessoal sobre mim mesmo, ter menos pensamentos triste e me sentir triste.', 'Sim, por alguns meses, mas não era continuo.', '9', 'De R$ 2.001 a R$ 5.000', 'Sim, estou disposto a investir pois preciso mudar.', 'Indicação da amiga da minha mãe', NULL, NULL, '[{"nome": "TRAVA DA APROVAÇÃO", "score": 8}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 7.6}, {"nome": "TRAVA DO SERVIDOR", "score": 7.2}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 7}, {"nome": "TRAVA PATERNA", "score": 6.8}, {"nome": "TRAVA DO AMBIENTE", "score": 6.8}, {"nome": "TRAVA DA VÍTIMA", "score": 6.6}, {"nome": "TRAVA DA ESCASSEZ", "score": 6.4}, {"nome": "TRAVA DA PROCRASTINAÇÃO", "score": 6.4}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 5}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
