INSERT INTO leads (origemid, terapeuta_slug, therapist_slug, tipoteste, versao_teste, data, nome, email, whatsapp, idade, profissao, infancia, adolescencia, vida_adulta, problemas, terapia_anterior, prioridade, renda, investir, indicacao, sessao_atual, desconfortos, resultadostravas, respostasdetalhadas, status, abordado, agendousessao, fechouprotocolo, arquivado)
VALUES ('c35ZJe88jnWcujmTK4Gz', 'mariland-rodrigues', 'mariland-rodrigues', 'aberto', 'v2-revisado', '2026-07-27T02:50:04.638Z'::timestamptz, 'Lean Dro', 'leandrogrocha@gmail.com', '41996824622', '47', 'designer de midia e tarapeuta florais', 'Minha infância foi marcada por uma mistura de amor, insegurança, comparação e sensação de não pertencimento. Cresci em uma casa simples em uma rua onde a maioria das famílias tinha uma condição financeira melhor que a nossa. Eu via outras crianças com brinquedos importados, roupas bonitas e mais oportunidades, e frequentemente me sentia menor ou menos importante por causa disso.

Meu pai saiu da minha vida muito cedo. Uma das lembranças que mais me marcaram foi quando, ainda criança, eu testei se ele realmente queria ficar comigo. Pedi para voltar para morar com minha mãe esperando que ele me impedisse, mas ele simplesmente me levou. Quando percebi que realmente iria embora, chorei desesperadamente. Aquilo ficou gravado em mim como uma sensação de abandono.

Minha mãe trabalhava muito e fez o que podia, mas também era explosiva e crítica em muitos momentos. Eu me lembro de ser comparado com outras crianças, principalmente um amigo chamado Alceu. Isso me fazia sentir inadequado e com a impressão de que eu deveria ser outra pessoa para ser aceito.

Também sofri bullying na escola e muitas vezes me refugiei na imaginação, nos videogames, nos desenhos, na música e nos meus próprios pensamentos. Hoje percebo que boa parte da minha infância foi tentando encontrar um lugar onde eu me sentisse seguro e aceito.', 'Na adolescência comecei a desenvolver minha identidade através do skate, da música e da cultura hip hop. Foi uma época em que encontrei algo que parecia realmente meu. Ao mesmo tempo, continuei carregando sentimentos de inadequação, comparação e baixa autoestima.

Eu tinha muitos sonhos, mas frequentemente me sentia inferior a outras pessoas. Via colegas que pareciam mais inteligentes, mais ricos ou mais preparados e concluía que eu nunca chegaria ao mesmo nível. Passei muito tempo me comparando com pessoas extremamente talentosas e isso acabava me paralisando.

Também convivi durante anos com epilepsia, o que trouxe limitações e preocupações. Sentia que precisava provar meu valor o tempo todo. Apesar disso, fui autodidata em muitas áreas e desenvolvi interesse por tecnologia, música, design e idiomas.

Foi uma fase em que comecei a acreditar que tinha potencial, mas ao mesmo tempo carregava a sensação de que havia algo errado comigo ou que eu não merecia ocupar certos espaços.', 'Minha vida adulta foi marcada por muitas tentativas de construir algo significativo. Trabalhei com tecnologia, design, audiovisual, música e morei 11 anos no Japão. Tive experiências profissionais importantes, mas também vivi períodos de muita pressão, solidão e desgaste emocional.

Passei por relacionamentos importantes, perdas afetivas, dificuldades financeiras e questões relacionadas à saúde mental. Em determinado momento tive um surto psicótico após o uso de ayahuasca combinado com antidepressivos, o que gerou consequências que ainda estou elaborando.

Hoje percebo que ainda carrego sentimentos antigos de rejeição, abandono e inadequação. Muitas vezes sinto que preciso provar meu valor ou que qualquer crítica significa que não sou bom o suficiente. Também percebo uma tendência a me paralisar diante de projetos importantes, mesmo tendo capacidade para realizá-los.

Ao mesmo tempo, reconheço que desenvolvi muitas habilidades ao longo da vida. Sou produtor musical, DJ, terapeuta integrativo, designer, editor de vídeo, criador de conteúdo e tenho facilidade para aprender sozinho. Atualmente estou tentando organizar minha vida de forma mais saudável, fortalecer minha autoestima e construir uma relação melhor comigo mesmo.', 'Gostaria de trabalhar sentimentos profundos de rejeição, abandono e inadequação. Quero parar de me sentir constantemente avaliado ou diminuído pelos outros. Também quero reduzir a procrastinação, a autossabotagem e a dificuldade de transformar ideias em ação. Desejo desenvolver mais autoconfiança, estabilidade emocional e aprender a me valorizar sem depender tanto da aprovação externa.', 'Sim. Já fiz psicoterapia, acompanhamento psicológico e psiquiátrico, participei do CAPS e também realizei estudos e práticas de desenvolvimento pessoal, terapia integrativa, florais, espiritualidade e autoconhecimento ao longo dos últimos anos', '10', 'De R$ 5.001 a R$ 8.000', 'Não tenho condições de investir', 'Encontrei através da internet e de pesquisas relacionadas a terapia, autoconhecimento e desenvolvimento pessoal.', NULL, NULL, '[{"nome": "TRAVA PATERNA", "score": 8.4}, {"nome": "TRAVA DA COMPETÊNCIA", "score": 8.2}, {"nome": "TRAVA DA ESCASSEZ", "score": 8}, {"score": 7.8, "nome": "TRAVA DA PROCRASTINAÇÃO"}, {"nome": "TRAVA DA VÍTIMA", "score": 7.4}, {"nome": "TRAVA DO SERVIDOR", "score": 7.4}, {"nome": "TRAVA DO AMBIENTE", "score": 7.4}, {"nome": "TRAVA DA AUTOCONFIANÇA", "score": 7}, {"nome": "TRAVA DA PERFEIÇÃO", "score": 7}, {"nome": "TRAVA DA APROVAÇÃO", "score": 6}]'::jsonb, '[]'::jsonb, 'novo_questionario', false, false, false, false)
ON CONFLICT (origemid) DO NOTHING;

